<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { detalleConvenio,listarConvenios,registrarConvenio,type Convenio,type Options } from '../services/convenios'
const rows=ref<Convenio[]>([]),options=ref<Options>({tipos:[],estados:[],personas:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detail=ref<Convenio|null>(null),file=ref<File|null>(null),personSearch=ref('')
const filters=reactive({criterio:'',tipo:'',estado:'',persona:'',page:1}),form=reactive({codigo_convenio:'',tipo_convenio_id:'',personas:[] as number[],objeto:'',fecha_suscripcion:'',fecha_inicio:'',fecha_fin:'',monto:'',dias_alerta:30,documento_referencia_externo:'',observaciones:''})
const people=computed(()=>options.value.personas.filter(x=>!personSearch.value||x.nombre.toLowerCase().includes(personSearch.value.toLowerCase())||x.documento?.includes(personSearch.value)).slice(0,40))
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarConvenios(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;options.value=r.options}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(){Object.assign(form,{codigo_convenio:options.value.codigo_sugerido||'',tipo_convenio_id:'',personas:[],objeto:'',fecha_suscripcion:'',fecha_inicio:'',fecha_fin:'',monto:'',dias_alerta:30,documento_referencia_externo:'',observaciones:''});file.value=null;personSearch.value='';modal.value=true}function toggle(id:number){form.personas=form.personas.includes(id)?form.personas.filter(x=>x!==id):[...form.personas,id]}
async function save(){if(!form.codigo_convenio||!form.tipo_convenio_id||!form.personas.length||!form.objeto||!form.fecha_suscripcion||!form.fecha_inicio||!form.fecha_fin||!file.value){error.value='Complete los datos obligatorios, seleccione una contraparte y adjunte el convenio.';return}if(form.fecha_inicio<form.fecha_suscripcion||form.fecha_fin<=form.fecha_inicio){error.value='Revise la secuencia de las fechas de suscripción y vigencia.';return}const data=new FormData();Object.entries(form).forEach(([k,v])=>{if(k==='personas')(v as number[]).forEach(id=>data.append('personas[]',String(id)));else if(v!=='')data.append(k,String(v))});data.append('archivo_principal',file.value);saving.value=true;error.value='';try{await registrarConvenio(data);modal.value=false;success.value='Convenio registrado correctamente.';await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:Convenio){try{detail.value=await detalleConvenio(item.id)}catch(e){error.value=message(e)}}function choose(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null}function money(v?:number){return v==null?'—':new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(v)}function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / MAT / Convenios</nav><header class="hero"><div class="mark">CV</div><div><small>MAT · LEGAL</small><h1>Gestión de convenios</h1><p>Vigencias, contrapartes, compromisos y documentos institucionales.</p></div><strong>{{total}} convenios</strong><button @click="open">+ Nuevo convenio</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Código u objeto" @keyup.enter="load(1)"></label><label>Tipo<select v-model="filters.tipo"><option value="">Todos</option><option v-for="x in options.tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option v-for="x in options.estados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Contraparte<select v-model="filters.persona"><option value="">Todas</option><option v-for="x in options.personas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando convenios…</div><div v-else-if="!rows.length" class="empty">No se encontraron convenios.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id" :class="{warning:item.esta_por_vencer,danger:item.esta_vencido}"><header><div><small>{{item.tipo}}</small><b>{{item.codigo_convenio}}</b></div><em>{{item.estado}}</em></header><p>{{item.objeto}}</p><div class="dates"><span><small>Inicio</small>{{item.fecha_inicio}}</span><span><small>Fin vigente</small>{{item.fecha_fin_vigente||item.fecha_fin}}</span><span><small>Monto vigente</small>{{money(item.monto_vigente??item.monto)}}</span></div><div class="people"><span v-for="x in item.personas" :key="x.id">{{x.nombre}}</span></div><footer><i v-if="item.esta_por_vencer">Próximo a vencer</i><i v-else-if="item.esta_vencido">Vencido</i><span v-else></span><button @click="show(item)">Ver ficha</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>NUEVO REGISTRO</small><h2>Registrar convenio</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model.trim="form.codigo_convenio" maxlength="200"></label><label>Tipo *<select v-model="form.tipo_convenio_id"><option value="">Seleccione</option><option v-for="x in options.tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Suscripción *<input v-model="form.fecha_suscripcion" type="date"></label><label>Inicio *<input v-model="form.fecha_inicio" type="date"></label><label>Fin *<input v-model="form.fecha_fin" type="date"></label><label>Días de alerta<input v-model="form.dias_alerta" type="number" min="1" max="365"></label><label>Monto<input v-model="form.monto" type="number" min="0" step="0.01"></label><label>Documento de referencia<input v-model.trim="form.documento_referencia_externo" maxlength="200"></label></div><label>Objeto *<textarea v-model.trim="form.objeto" maxlength="500" rows="3"></textarea></label><h3>Contrapartes *</h3><input v-model.trim="personSearch" placeholder="Buscar por nombre o documento"><div class="selector"><button v-for="x in people" :key="x.id" type="button" :class="{selected:form.personas.includes(x.id)}" @click="toggle(x.id)"><b>{{x.nombre}}</b><span>{{x.documento}}</span><em>{{form.personas.includes(x.id)?'✓':''}}</em></button></div><label>Documento principal *<input type="file" accept="application/pdf" @change="choose"><small>Archivo PDF del convenio.</small></label><label>Observaciones<textarea v-model.trim="form.observaciones" rows="2"></textarea></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar convenio'}}</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>FICHA DEL CONVENIO</small><h2>{{detail.codigo_convenio}}</h2><p>{{detail.tipo}} · {{detail.estado}}</p></div><button @click="detail=null">×</button></header><p class="object">{{detail.objeto}}</p><div class="summary"><div><b>{{detail.fecha_fin_vigente||detail.fecha_fin}}</b><span>Fin vigente</span></div><div><b>{{money(detail.monto_vigente??detail.monto)}}</b><span>Monto vigente</span></div><div><b>{{detail.compromisos?.length||0}}</b><span>Compromisos</span></div><div><b>{{detail.adjuntos?.length||0}}</b><span>Archivos</span></div></div><h3>Contrapartes</h3><div class="list"><div v-for="x in detail.personas" :key="x.id"><b>{{x.nombre}}</b><span>{{x.documento}}</span></div></div><h3>Compromisos</h3><div class="list"><p v-if="!detail.compromisos?.length">Sin compromisos registrados.</p><div v-for="x in detail.compromisos" :key="x.id"><b>{{x.descripcion}}</b><span>{{x.fecha_programada}} · {{x.estado}}</span></div></div><h3>Prórrogas y modificaciones</h3><div class="list"><p v-if="!detail.prorrogas?.length&&!detail.modificaciones?.length">Sin movimientos registrados.</p><div v-for="x in detail.prorrogas" :key="'p'+x.id"><b>Prórroga: {{x.descripcion}}</b><span>Nuevo fin: {{x.fecha_fin_nueva}}</span></div><div v-for="x in detail.modificaciones" :key="'m'+x.id"><b>Modificación: {{x.tipo}}</b><span>{{x.descripcion}}</span></div></div><h3>Documentos</h3><div class="list"><div v-for="x in detail.adjuntos" :key="x.id"><b>{{x.nombre_original}}</b><span>{{x.tipo}}</span></div></div><footer><button class="clear" @click="detail=null">Cerrar</button></footer></section></div></div></template>
<style scoped>
.page{--accent:#596a7b;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.56rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:8px;border-radius:9px;background:#fff}.filters label{flex:1;font-size:.53rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.6rem}.cards{margin-top:13px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{display:flex;flex-direction:column;padding:14px;border-top:3px solid var(--accent);border-radius:9px;background:#fff}.cards article.warning{border-color:#c88a2d}.cards article.danger{border-color:#b44747}.cards article>header,.cards article>footer{display:flex;align-items:center;justify-content:space-between;gap:8px}.cards header b,.cards header small{display:block}.cards header em{padding:4px 7px;border-radius:10px;background:#edf1f3;font-size:.49rem;font-style:normal}.cards article>p{min-height:45px;color:#66757c;font-size:.56rem}.dates{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.dates span{font-size:.53rem;font-weight:700}.dates small{display:block;color:#8a969c;font-size:.46rem}.people{margin-top:10px}.people span{display:block;padding:3px 0;border-bottom:1px solid #eef1f2;font-size:.5rem}.cards footer{margin-top:auto;padding-top:9px}.cards footer i{color:#b46c25;font-size:.5rem}.cards footer button{border:0;color:var(--accent);background:none;font-size:.52rem;font-weight:700}.empty{margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,820px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.modal label small{display:block;margin-top:4px;color:#89959b}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.modal h3{font-size:.65rem}.selector{max-height:150px;margin:6px 0 12px;overflow:auto}.selector button{width:100%;padding:7px;display:grid;grid-template-columns:1fr 100px 20px;border:0;border-bottom:1px solid #e8ecee;background:#fff;text-align:left;font-size:.53rem}.selector button.selected{background:#edf1f3}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.object{padding:12px;border-left:3px solid var(--accent);background:#f6f8f9;font-size:.6rem}.summary{margin:14px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.summary div{padding:11px;text-align:center;border-radius:7px;background:#f0f3f5}.summary b,.summary span{display:block;font-size:.55rem}.list div{padding:8px;display:flex;justify-content:space-between;gap:8px;border-bottom:1px solid #e8ecee;font-size:.56rem}.list span,.list>p{color:#7d898f}.detail{width:min(100%,900px)}@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:560px){.cards,.grid,.summary{grid-template-columns:1fr}}
</style>
